rows = [{'id': 1, 'amount': 30.0}, {'id': 2, 'amount': 150.0}, {'id': 3, 'amount': 90.0}]

def to_columns(rows):
    return {k: [r[k] for r in rows] for k in rows[0]}

def to_rows(columns):
    keys = list(columns)
    return [dict(zip(keys, values)) for values in zip(*columns.values())]

cols = to_columns(rows)
print('columns:', cols)
print('average amount:', round(sum(cols['amount']) / len(cols['amount']), 2))
print('round trip equal:', to_rows(cols) == rows)

