CREATE TABLE mart_country_revenue AS
SELECT c.country, SUM(i.qty * p.unit_price) AS revenue
FROM purchase o
JOIN customer c ON c.customer_id = o.customer_id
JOIN order_item i ON i.order_id = o.order_id
JOIN product p ON p.product_id = i.product_id
WHERE o.status = 'paid'
GROUP BY c.country;

SELECT m.mart_total, s.source_total, m.mart_total = s.source_total AS equal
FROM (SELECT SUM(revenue) AS mart_total FROM mart_country_revenue) m,
     (SELECT SUM(i.qty * p.unit_price) AS source_total
      FROM purchase o JOIN order_item i ON i.order_id = o.order_id JOIN product p ON p.product_id = i.product_id
      WHERE o.status = 'paid') s;
